import pandas as pd
import numpy as np

def fill_missing(df, column, value):
    if not isinstance(df, pd.DataFrame):
        raise TypeError("Input must be a pandas DataFrame")
    if column not in df.columns:
        raise ValueError("Column does not exist in the DataFrame")
    if not pd.api.types.is_numeric_dtype(df[column]) and not pd.api.types.is_string_dtype(df[column]):
        raise ValueError("Column must be of numeric or string type")
    df[column] = df[column].fillna(value)
    return df
